//! qedgen Kani codegen — the sole Kani path, consuming `mir::Mir` + the
//! originating `ParsedSpec` (passed through to the shared
//! `rust_codegen_util::emit_*` helpers). Output pinned by `tests/kani_snapshot.rs`.
//!
//! `generate` emits: structural prefix (banner / math helpers / state-model
//! header / file-scoped constants), per-account sections (multi-account wraps
//! each in `mod <lowercase>`; covers/liveness/env emit in single mode only),
//! then the `DO NOT EDIT BELOW` footer. sBPF specs never reach this module —
//! `qedgen codegen --kani` skips assembly targets (Lean + client tests instead).

use anyhow::Result;
use std::path::Path;

use crate::check::ParsedSpec;
use crate::codegen_shared::{write_generated_file, DslTypeExt};
use crate::mir::Mir;

/// Generate the Kani harness file at `output_path` from a pre-lowered
/// `Mir` + the originating `ParsedSpec`.
pub fn generate(mir: &Mir, parsed: &ParsedSpec, output_path: &Path) -> Result<()> {
    if mir.handlers.is_empty() {
        anyhow::bail!("No operations found in the spec — is this a valid qedspec file?");
    }

    crate::rust_codegen_util::check_effect_targets(parsed)?;

    let content = render_with_progress(mir, parsed);
    write_generated_file(output_path, &content)?;

    eprintln!("Generated Kani harnesses in {}", output_path.display());
    Ok(())
}

/// Pure render: deterministic structural prefix, then the per-account
/// body, branching on single- vs multi-account.
#[cfg_attr(not(test), allow(dead_code))]
pub fn render(mir: &Mir, parsed: &ParsedSpec) -> String {
    render_inner(mir, parsed, false, false)
}

fn render_with_progress(mir: &Mir, parsed: &ParsedSpec) -> String {
    render_inner(mir, parsed, true, skip_guard_proofs_from_env())
}

fn render_inner(mir: &Mir, parsed: &ParsedSpec, progress: bool, skip_guard_proofs: bool) -> String {
    let mut out = String::new();
    if progress {
        eprintln!(
            "Rendering Kani model harnesses for {} handler(s), {} propertie(s), {} invariant(s)",
            parsed.handlers.len(),
            parsed.properties.len(),
            parsed.invariants.len()
        );
    }
    emit_header(&mut out, parsed);
    emit_math_helpers(&mut out, parsed);
    if crate::rust_codegen_util::spec_uses_pubkey(parsed) {
        crate::rust_codegen_util::emit_kani_pubkey_helpers(&mut out);
    }
    emit_state_model_header(&mut out);
    emit_constants(&mut out, mir);

    if parsed.account_types.len() > 1 {
        // Multi-account: per-account `mod <lowercase>` blocks; file-level
        // features (covers / liveness / env) emit in single mode only.
        if let Err(e) =
            emit_multi_account_sections(&mut out, mir, parsed, progress, skip_guard_proofs)
        {
            out.push_str(&format!("// MIR-ERROR: multi-account emit failed: {}\n", e));
        }
    } else {
        if let Err(e) =
            emit_single_account_sections(&mut out, mir, parsed, progress, skip_guard_proofs)
        {
            out.push_str(&format!(
                "// MIR-ERROR: single-account emit failed: {}\n",
                e
            ));
        }
    }

    out.push_str("// ---- GENERATED BY QEDGEN — DO NOT EDIT BELOW THIS LINE ----\n");
    out
}

fn skip_guard_proofs_from_env() -> bool {
    matches!(
        std::env::var("QEDGEN_KANI_SKIP_GUARD_PROOFS")
            .ok()
            .as_deref(),
        Some("1" | "true" | "TRUE" | "yes" | "YES")
    )
}

/// Single-account dispatch — every section emitter in snapshot-pinned order.
fn emit_single_account_sections(
    out: &mut String,
    mir: &Mir,
    parsed: &ParsedSpec,
    progress: bool,
    skip_guard_proofs: bool,
) -> Result<()> {
    if progress {
        eprintln!("Rendering Kani section: state model");
    }
    emit_account_section_structural(out, mir, parsed)?;
    if skip_guard_proofs {
        if progress {
            eprintln!(
                "Skipping Kani section: guard rejection proofs (QEDGEN_KANI_SKIP_GUARD_PROOFS=1)"
            );
        }
    } else {
        if progress {
            eprintln!("Rendering Kani section: guard rejection proofs");
        }
        emit_guard_enforcement_harnesses(out, parsed, progress)?;
    }
    if progress {
        eprintln!("Rendering Kani section: abort-condition proofs");
    }
    emit_abort_condition_harnesses(out, parsed)?;
    if progress {
        eprintln!("Rendering Kani section: property preservation proofs");
    }
    emit_property_preservation_harnesses(out, parsed)?;
    // Section order (property → ensures → invariant → effect → overflow)
    // is load-bearing for snapshot byte-equivalence.
    if progress {
        eprintln!("Rendering Kani section: ensures preservation proofs");
    }
    emit_ensures_preservation_harnesses(out, parsed)?;
    if progress {
        eprintln!("Rendering Kani section: invariant preservation proofs");
    }
    emit_invariant_preservation_harnesses(out, parsed)?;
    if progress {
        eprintln!("Rendering Kani section: effect conformance proofs");
    }
    emit_effect_conformance_harnesses(out, mir, parsed)?;
    if progress {
        eprintln!("Rendering Kani section: overflow proofs");
    }
    emit_overflow_detection_harnesses(out, mir, parsed)?;
    // File-level features (covers / liveness / environment) —
    // single-mode only; multi-account specs skip these entirely.
    if progress {
        eprintln!("Rendering Kani section: cover/liveness/environment proofs");
    }
    emit_file_level_features(out, parsed)?;
    Ok(())
}

/// Multi-account dispatch — one `mod <lowercase> { use super::*; ... }`
/// per account_type, each driven by a per-account scoped `ParsedSpec`
/// (see `scope_parsed_to_account`). Sections follow the same order as
/// single-mode; file-level features (covers / liveness / environment)
/// are not emitted in multi-mode at all.
fn emit_multi_account_sections(
    out: &mut String,
    mir: &Mir,
    parsed: &ParsedSpec,
    progress: bool,
    skip_guard_proofs: bool,
) -> Result<()> {
    use crate::rust_codegen_util as util;

    for acct in &parsed.account_types {
        let acct_fields_view = util::mutable_fields(&acct.fields);
        if acct_fields_view.is_empty() {
            continue;
        }

        let scoped = scope_parsed_to_account(parsed, acct);

        if scoped.handlers.is_empty() {
            continue;
        }

        let mod_name = acct.name.to_lowercase();
        if progress {
            eprintln!("Rendering Kani account module: {mod_name}");
        }
        out.push_str(&format!("mod {} {{\n", mod_name));
        out.push_str("    use super::*;\n\n");

        emit_account_section_structural(out, mir, &scoped)?;
        if skip_guard_proofs {
            if progress {
                eprintln!(
                    "Skipping Kani section: guard rejection proofs (QEDGEN_KANI_SKIP_GUARD_PROOFS=1)"
                );
            }
        } else {
            emit_guard_enforcement_harnesses(out, &scoped, progress)?;
        }
        emit_abort_condition_harnesses(out, &scoped)?;
        emit_property_preservation_harnesses(out, &scoped)?;
        emit_ensures_preservation_harnesses(out, &scoped)?;
        emit_invariant_preservation_harnesses(out, &scoped)?;
        emit_effect_conformance_harnesses(out, mir, &scoped)?;
        emit_overflow_detection_harnesses(out, mir, &scoped)?;

        out.push_str(&format!("}} // mod {}\n\n", mod_name));
    }

    Ok(())
}

/// Build a per-account scoped `ParsedSpec` view the section emitters can
/// consume unchanged:
///
///   * `account_types` → `vec![acct]` so the single-account view resolve
///     picks up this account's fields/lifecycle.
///   * `handlers` → strict `on_account == Some(acct.name)` (no primary
///     fallback).
///   * `properties` → substring match against any field of this account.
///   * `invariants` → those mentioned by at least one filtered handler.
///   * Spec-wide collections (records, sum_types, constants, interfaces,
///     ref_impls, lifecycle_states, state_fields, error_codes) cloned
///     verbatim — file-scoped, shared across `mod` blocks via `use super::*;`.
fn scope_parsed_to_account(
    parsed: &ParsedSpec,
    acct: &crate::check::ParsedAccountType,
) -> ParsedSpec {
    let mut scoped = parsed.clone();

    scoped.account_types = vec![acct.clone()];

    scoped.handlers = parsed
        .handlers
        .iter()
        .filter(|h| h.on_account.as_deref() == Some(acct.name.as_str()))
        .cloned()
        .collect();

    let acct_field_names: Vec<&str> = acct.fields.iter().map(|(n, _)| n.as_str()).collect();
    scoped.properties = parsed
        .properties
        .iter()
        .filter(|p| {
            if let Some(ref expr) = p.expression {
                acct_field_names.iter().any(|f| expr.contains(f))
            } else {
                false
            }
        })
        .cloned()
        .collect();

    let claimed_inv_names: std::collections::HashSet<&str> = scoped
        .handlers
        .iter()
        .flat_map(|h| h.invariants.iter().chain(h.establishes.iter()))
        .map(|s| s.as_str())
        .collect();
    scoped.invariants = parsed
        .invariants
        .iter()
        .filter(|i| claimed_inv_names.contains(i.name.as_str()))
        .cloned()
        .collect();

    scoped
}

// ----------------------------------------------------------------------
// Section emitters — structural prefix
// ----------------------------------------------------------------------

/// File header: banner with the `tests/kani.rs` fingerprint hash.
fn emit_header(out: &mut String, parsed: &ParsedSpec) {
    let fp = crate::fingerprint::compute_fingerprint(parsed);
    let hash = fp
        .file_hashes
        .get("tests/kani.rs")
        .cloned()
        .unwrap_or_default();

    out.push_str(&crate::banner::banner(None, &hash));
    out.push_str("//\n");
    out.push_str("// Self-contained Kani proof harnesses for the spec.\n");
    out.push_str("//\n");
    out.push_str("// These proofs verify the spec's transition design using Kani bounded model\n");
    out.push_str("// checking. They operate on a pure model of the state machine (derived from\n");
    out.push_str("// the qedspec), independent of framework (Quasar/Anchor) types.\n");
    out.push_str("//\n");
    out.push_str("//   Lean proves:  transition functions preserve invariants (∀ states)\n");
    out.push_str(
        "//   Kani checks:  same properties via bounded model checking + overflow detection\n",
    );
    out.push_str("//   Together:     high assurance that the spec design is correct\n");
    out.push_str("//\n");
    out.push_str("// To run:  cargo kani --harness <name>   (requires cargo-kani)\n");
    out.push_str("// ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ---- ----\n");
    out.push_str("#![cfg(kani)]\n\n");
}

/// Math helpers (`mul_div_floor_u128` / `mul_div_ceil_u128`), inlined only
/// when the spec's guards reference them, so the standalone harness
/// compiles without depending on `src/math.rs`.
fn emit_math_helpers(out: &mut String, parsed: &ParsedSpec) {
    // The backslash-continuation strings deliberately drop per-line body
    // indentation — that un-indented shape is what every committed kani.rs
    // fixture/snapshot was generated against. Don't re-indent.
    if crate::codegen_shared::guards_use_math_helpers(parsed) {
        out.push_str(
            "#[allow(dead_code)]\n\
#[inline]\n\
fn mul_div_floor_u128(a: u128, b: u128, d: u128) -> u128 {\n\
    if d == 0 { return 0; }\n\
    a.saturating_mul(b) / d\n\
}\n\n\
#[allow(dead_code)]\n\
#[inline]\n\
fn mul_div_ceil_u128(a: u128, b: u128, d: u128) -> u128 {\n\
    if d == 0 { return 0; }\n\
    let prod = a.saturating_mul(b);\n\
    if prod % d == 0 { prod / d } else { (prod / d).saturating_add(1) }\n\
}\n\n",
        );
    }

    if crate::rust_codegen_util::spec_uses_kani_bps_mul_div_helper(parsed) {
        out.push_str(
            "#[allow(dead_code)]\n\
#[inline]\n\
fn mul_bps_floor_u128(a: u128, bps: u128) -> u128 {\n\
    if bps > 10000 { return u128::MAX; }\n\
    let b = (bps as u16) as u128;\n\
    let q = a / 10000;\n\
    let r = a % 10000;\n\
    q.wrapping_mul(b).wrapping_add(r.wrapping_mul(b) / 10000)\n\
}\n\n",
        );
    }
}

/// State model header banner — always emitted, even with no declared state.
fn emit_state_model_header(out: &mut String) {
    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// State model (derived from qedspec — no framework dependencies)\n");
    out.push_str(
        "// ============================================================================\n\n",
    );
}

/// File-scoped constants, one per `Mir.constants` entry. Per-ADT modules
/// reference them via `use super::*`, so they live at file scope rather
/// than being duplicated.
fn emit_constants(out: &mut String, mir: &Mir) {
    if mir.constants.is_empty() {
        return;
    }
    crate::rust_codegen_util::emit_constants(out, &mir.constants);
}

// ----------------------------------------------------------------------
// Section emitters — per-account structural body
// ----------------------------------------------------------------------

/// Per-account structural body: records / unit-enum sums / Status /
/// State / property predicates / invariant predicates / transition fns /
/// ref_impls. Harnesses are emitted by the later sections.
fn emit_account_section_structural(out: &mut String, mir: &Mir, parsed: &ParsedSpec) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    // Resolve view: single `type Account` block → its fields + lifecycle;
    // none → `resolve_state_fields` + `spec.lifecycle_states`.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            // Multi-account reaching this path: best-effort primary-account
            // view (multi-mode dispatch passes a single-account scoped spec).
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };

    // Ghosts are spec-only verification-State fields: present in the Kani
    // State struct + symbolic init + transitions (BMC can read them,
    // `emit_transition_fn` can assign them), never in the on-chain program.
    let state_fields_with_ghosts: Vec<(String, String)> = state_fields
        .iter()
        .cloned()
        .chain(parsed.ghosts.iter().map(|g| (g.name.clone(), g.ty.clone())))
        .collect();
    let state_fields: &[(String, String)] = &state_fields_with_ghosts;

    let mutable = util::mutable_fields(state_fields);
    let has_lifecycle = lifecycle.len() >= 2;

    util::emit_record_structs(out, parsed, "Clone, Copy, kani::Arbitrary", |t| {
        map_type(t, parsed)
    })?;

    util::emit_unit_enum_sums(out, parsed, "Clone, Copy, PartialEq, Eq, kani::Arbitrary")?;

    util::emit_lifecycle_status_enum_from(
        out,
        lifecycle,
        "Clone, Copy, PartialEq, Eq, kani::Arbitrary",
    );

    util::emit_state_struct_with_lifecycle(
        out,
        &mutable,
        "Clone, Copy",
        |t| map_type(t, parsed),
        has_lifecycle,
    )?;
    emit_kani_account_env_structs(out, parsed);

    let handlers: Vec<&crate::check::ParsedHandler> = parsed.handlers.iter().collect();
    let properties: Vec<&crate::check::ParsedProperty> = parsed.properties.iter().collect();
    if !properties.is_empty() {
        out.push_str(
            "// ============================================================================\n",
        );
        out.push_str("// Property predicates (from qedspec `property` declarations)\n");
        out.push_str(
            "// ============================================================================\n\n",
        );
        // `emit_property_predicates_with` takes `&[ParsedProperty]`, not
        // `&[&_]` — rebuild an owned Vec.
        let owned: Vec<crate::check::ParsedProperty> =
            properties.iter().map(|p| (*p).clone()).collect();
        util::emit_property_predicates_with(out, &owned, false, |t| map_type(t, parsed));
    }

    // Invariant predicates — only those linked from a handler in this section.
    let linked_invs: Vec<&crate::check::ParsedInvariant> = parsed
        .invariants
        .iter()
        .filter(|i| {
            handlers
                .iter()
                .any(|h| h.invariants.contains(&i.name) || h.establishes.contains(&i.name))
        })
        .collect();
    if !linked_invs.is_empty() {
        out.push_str(
            "// ============================================================================\n",
        );
        out.push_str("// Invariant predicates (from qedspec `invariant` declarations linked via\n");
        out.push_str(
            "// handler-side `invariant Name` clauses). v2.17.x wires ParsedInvariant.rust_expr\n",
        );
        out.push_str("// through to per-(handler, invariant) BMC preservation harnesses below.\n");
        out.push_str(
            "// ============================================================================\n\n",
        );
        util::emit_invariant_predicates(out, &linked_invs);
    }

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Transition functions (from qedspec operations — effects + guards)\n");
    out.push_str("//\n");
    out.push_str("// Each returns true if the guard passes and the transition fires,\n");
    out.push_str("// false if the guard rejects the operation.\n");
    out.push_str(
        "// ============================================================================\n\n",
    );
    for op in &handlers {
        util::emit_transition_fn_for_kani(out, mir, op, parsed, false, |t| map_type(t, parsed))?;
    }

    // Reference implementations — pure-expression fns callable from
    // ensures-preservation harnesses.
    if !parsed.ref_impls.is_empty() {
        out.push_str(
            "// ============================================================================\n",
        );
        out.push_str("// Reference implementations (from qedspec ref_impl declarations).\n");
        out.push_str(
            "// ============================================================================\n\n",
        );
        for r in &parsed.ref_impls {
            let params = r
                .params
                .iter()
                .map(|(n, t)| {
                    map_type(t, parsed)
                        .map(|rt| format!("{}: {}", n, rt))
                        .unwrap_or_else(|_| format!("{}: {}", n, t))
                })
                .collect::<Vec<_>>()
                .join(", ");
            let ret = map_type(&r.return_type, parsed).unwrap_or_else(|_| r.return_type.clone());
            out.push_str(&format!(
                "fn {}({}) -> {} {{\n    {}\n}}\n\n",
                r.name, params, ret, r.rust_body
            ));
        }
    }

    Ok(())
}

fn emit_kani_account_env_structs(out: &mut String, parsed: &ParsedSpec) {
    use crate::rust_codegen_util as util;

    let handlers: Vec<&crate::check::ParsedHandler> = parsed
        .handlers
        .iter()
        .filter(|op| util::handler_needs_account_env(op))
        .collect();
    if handlers.is_empty() {
        return;
    }

    out.push_str("#[derive(Clone, Copy)]\n");
    out.push_str("struct KaniAccount {\n");
    out.push_str("    pubkey: [u8; 32],\n");
    out.push_str("}\n\n");

    for op in handlers {
        out.push_str("#[derive(Clone, Copy)]\n");
        out.push_str(&format!(
            "struct {} {{\n",
            util::handler_account_env_struct_name(&op.name)
        ));
        for account in &op.accounts {
            out.push_str(&format!("    {}: KaniAccount,\n", account.name));
        }
        out.push_str("}\n\n");
    }
}

fn emit_kani_account_env_binding(
    out: &mut String,
    op: &crate::check::ParsedHandler,
    var_name: &str,
    indent: &str,
) {
    use crate::rust_codegen_util as util;

    if !util::handler_needs_account_env(op) {
        return;
    }

    out.push_str(&format!(
        "{indent}let {var_name} = {} {{\n",
        util::handler_account_env_struct_name(&op.name)
    ));
    for account in &op.accounts {
        out.push_str(&format!(
            "{indent}    {}: KaniAccount {{ pubkey: kani::any() }},\n",
            account.name
        ));
    }
    out.push_str(&format!("{indent}}};\n"));
}

fn transition_call_args(op: &crate::check::ParsedHandler, account_var: Option<&str>) -> String {
    use crate::rust_codegen_util as util;

    let mut args = String::new();
    if util::handler_needs_account_env(op) {
        let account_var = account_var.expect("account var provided for account-env handler");
        args.push_str(&format!(", &{}", account_var));
    }
    for (n, _) in op.takes_params.iter().chain(op.abstract_binders.iter()) {
        args.push_str(&format!(", {}", n));
    }
    args
}

// ----------------------------------------------------------------------
// Section emitters — guard-enforcement harnesses
// ----------------------------------------------------------------------

/// Emit `#[kani::proof] fn verify_<handler>_rejects_invalid()` per handler
/// with a guard or `requires` clause. One monolithic harness per handler up
/// to the split threshold, then one harness per guard term:
///   * symbolic state init (+ pre-status assume if lifecycle-gated)
///   * every param + abstract binder as `kani::any()`
///   * `kani::assume(!(full_guard))` — at least one guard component violated
///   * `assert!(!<handler>(&mut s, args...))` — handler must reject
fn emit_guard_enforcement_harnesses(
    out: &mut String,
    parsed: &ParsedSpec,
    progress: bool,
) -> Result<()> {
    use crate::rust_codegen_util as util;

    const GUARD_REJECTION_SPLIT_THRESHOLD: usize = 8;

    // Resolve view — same logic as `emit_account_section_structural`.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);

    let guard_ops: Vec<&crate::check::ParsedHandler> =
        parsed.handlers.iter().filter(|op| op.has_guard()).collect();

    if guard_ops.is_empty() {
        return Ok(());
    }

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Guard enforcement — transitions reject invalid inputs\n");
    out.push_str(
        "// ============================================================================\n\n",
    );

    for op in &guard_ops {
        let guard_terms = util::collect_guard_terms_with_account_env(
            op,
            false,
            util::handler_needs_account_env(op).then_some("accounts"),
        );
        if guard_terms.is_empty() {
            // `has_guard()` but no expressible negation — skip to avoid
            // a vacuous `kani::assume(!(true))` harness.
            continue;
        }

        if guard_terms.len() <= GUARD_REJECTION_SPLIT_THRESHOLD {
            let full_guard = util::collect_full_guard_with_account_env(
                op,
                false,
                util::handler_needs_account_env(op).then_some("accounts"),
            )
            .expect("guard terms came from an expressible full guard");
            let full_guard = util::rewrite_kani_pubkey_comparisons(&full_guard, op, parsed);
            let harness_name = format!("verify_{}_rejects_invalid", op.name);
            if progress {
                eprintln!("Rendering Kani guard proof: {harness_name}");
            }
            emit_guard_rejection_harness(
                out,
                GuardRejectionHarness {
                    parsed,
                    op,
                    mutable: &mutable,
                    lifecycle,
                    harness_name: &harness_name,
                    prefix_terms: &[],
                    violated_expr: &full_guard,
                    assert_message: &format!("{} must reject when guard is violated", op.name),
                    direct_negated_assume: false,
                },
            )?;
        } else {
            for (idx, term) in guard_terms.iter().enumerate() {
                let term_expr = util::rewrite_kani_pubkey_comparisons(&term.rust_expr, op, parsed);
                let prefix_terms = guard_terms[..idx]
                    .iter()
                    .map(|prefix| {
                        util::rewrite_kani_pubkey_comparisons(&prefix.rust_expr, op, parsed)
                    })
                    .collect::<Vec<_>>();
                let slug = guard_term_slug(&term_expr);
                let harness_name =
                    format!("verify_{}_rejects_invalid_{}_{}", op.name, idx + 1, slug);
                if progress {
                    eprintln!("Rendering Kani guard proof: {harness_name}");
                }
                emit_guard_rejection_harness(
                    out,
                    GuardRejectionHarness {
                        parsed,
                        op,
                        mutable: &mutable,
                        lifecycle,
                        harness_name: &harness_name,
                        prefix_terms: &prefix_terms,
                        violated_expr: &term_expr,
                        assert_message: &format!(
                            "{} must reject when guard term is violated",
                            op.name
                        ),
                        direct_negated_assume: true,
                    },
                )?;
            }
        }
    }

    Ok(())
}

struct GuardRejectionHarness<'a> {
    parsed: &'a ParsedSpec,
    op: &'a crate::check::ParsedHandler,
    mutable: &'a [&'a (String, String)],
    lifecycle: &'a [String],
    harness_name: &'a str,
    prefix_terms: &'a [String],
    violated_expr: &'a str,
    assert_message: &'a str,
    direct_negated_assume: bool,
}

fn emit_guard_rejection_harness(out: &mut String, ctx: GuardRejectionHarness<'_>) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;
    let parsed = ctx.parsed;
    let op = ctx.op;
    let mutable = ctx.mutable;
    let lifecycle = ctx.lifecycle;
    let harness_name = ctx.harness_name;
    let prefix_terms = ctx.prefix_terms;
    let violated_expr = ctx.violated_expr;
    let assert_message = ctx.assert_message;
    let direct_negated_assume = ctx.direct_negated_assume;

    out.push_str("#[kani::proof]\n");
    out.push_str("#[kani::unwind(2)]\n");
    out.push_str("#[kani::solver(cadical)]\n");
    out.push_str(&format!("fn {harness_name}() {{\n"));

    util::emit_state_init_symbolic(out, mutable, lifecycle);
    util::emit_pre_status_assume(out, op, lifecycle);

    for (pname, ptype) in &op.takes_params {
        out.push_str(&format!(
            "    let {}: {} = kani::any();\n",
            pname,
            map_type(ptype, parsed)?
        ));
    }

    // Deliberate double-emit of abstract binders — bug-for-bug parity with
    // the snapshot-pinned output; cleanup deferred to v3.0.
    util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;
    util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;

    emit_kani_account_env_binding(out, op, "accounts", "    ");
    let mut helper_binding_counter = 0usize;
    for prefix in prefix_terms {
        let (prefix, bindings) = bind_kani_bps_floor_calls(prefix, &mut helper_binding_counter);
        for binding in bindings {
            out.push_str(&format!("    {binding}\n"));
        }
        out.push_str(&format!("    kani::assume({prefix});\n"));
    }
    let (violated_expr, bindings) =
        bind_kani_bps_floor_calls(violated_expr, &mut helper_binding_counter);
    for binding in bindings {
        out.push_str(&format!("    {binding}\n"));
    }
    // Assume the i-th guard component is violated. On the per-term split
    // path the prefix terms were already assumed true, so violating this
    // single term drives the full guard false.
    if direct_negated_assume {
        if let Some(negated) = util::negate_simple_top_level_comparison(&violated_expr) {
            out.push_str(&format!("    kani::assume({negated});\n"));
        } else {
            out.push_str(&format!("    kani::assume(!({violated_expr}));\n"));
        }
    } else {
        out.push_str(&format!("    kani::assume(!({violated_expr}));\n"));
    }

    // Per-arm vacuity guard: when term i is implied by the prefix terms,
    // this arm's assumption set is UNSAT and the assertion below is
    // unreachable — Kani would report SUCCESSFUL while proving nothing for
    // this arm. The cover makes that loud (an unsatisfied cover fails the
    // run) and doubles as a spec signal that the guard term is redundant.
    out.push_str("    kani::cover!(true, \"guard-violation domain is satisfiable\");\n");

    // With the guard violated, the generated transition must reject: it
    // returns `false` and applies none of its effects. Asserting the
    // negated term back (instead of calling the handler) would be a
    // tautology that proves nothing — the handler call is what gives the
    // harness teeth.
    let args = transition_call_args(
        op,
        util::handler_needs_account_env(op).then_some("accounts"),
    );
    out.push_str(&format!("    assert!(!{}(&mut s{}),\n", op.name, args));
    out.push_str(&format!("        \"{assert_message}\");\n"));
    out.push_str("}\n\n");

    Ok(())
}

fn bind_kani_bps_floor_calls(expr: &str, counter: &mut usize) -> (String, Vec<String>) {
    let helper_call = regex::Regex::new(
        r"mul_bps_floor_u128\((?P<a>[A-Za-z_][A-Za-z0-9_\.]*),\s*(?P<b>[A-Za-z_][A-Za-z0-9_\.]*)\)",
    )
    .expect("valid mul_bps_floor_u128 call regex");
    let mut rewritten = String::with_capacity(expr.len());
    let mut bindings = Vec::new();
    let mut cursor = 0usize;

    for captures in helper_call.captures_iter(expr) {
        let Some(call) = captures.get(0) else {
            continue;
        };
        rewritten.push_str(&expr[cursor..call.start()]);
        *counter += 1;
        let binding_name = format!("__qed_bps_floor_{counter}");
        let a = captures.name("a").expect("a capture").as_str();
        let b = captures.name("b").expect("b capture").as_str();
        bindings.push(format!(
            "let {binding_name} = mul_bps_floor_u128({a}, {b});"
        ));
        rewritten.push_str(&binding_name);
        cursor = call.end();
    }

    rewritten.push_str(&expr[cursor..]);
    (rewritten, bindings)
}

fn guard_term_slug(expr: &str) -> String {
    let mut slug = crate::codegen_shared::sanitize_ident(expr)
        .trim_matches('_')
        .to_ascii_lowercase();
    const MAX_SLUG_LEN: usize = 56;
    if slug.len() > MAX_SLUG_LEN {
        slug.truncate(MAX_SLUG_LEN);
        slug = slug.trim_end_matches('_').to_string();
    }
    if slug.is_empty() {
        "term".to_string()
    } else {
        slug
    }
}

// ----------------------------------------------------------------------
// Section emitters — abort-condition harnesses
// ----------------------------------------------------------------------

/// Emit `#[kani::proof] fn verify_<handler>_aborts_if_<error>()` per
/// (handler, abort clause): symbolic state + pre-status assume + symbolic
/// params + (double-emit) abstract binders, `kani::assume(<abort.rust_expr>)`
/// (the condition that should trigger abortion), then
/// `assert!(!<handler>(...))` — handler must reject.
fn emit_abort_condition_harnesses(out: &mut String, parsed: &ParsedSpec) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    // Resolve view — same logic as `emit_account_section_structural`.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);

    let abort_ops: Vec<&crate::check::ParsedHandler> = parsed
        .handlers
        .iter()
        .filter(|op| !op.aborts_if.is_empty())
        .collect();

    if abort_ops.is_empty() {
        return Ok(());
    }

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Abort conditions — operations must reject under specified conditions\n");
    out.push_str(
        "// ============================================================================\n\n",
    );

    for op in &abort_ops {
        for abort in &op.aborts_if {
            out.push_str("#[kani::proof]\n");
            out.push_str("#[kani::unwind(2)]\n");
            out.push_str("#[kani::solver(cadical)]\n");
            out.push_str(&format!(
                "fn verify_{}_aborts_if_{}() {{\n",
                op.name, abort.error_name
            ));

            util::emit_state_init_symbolic(out, &mutable, lifecycle);
            util::emit_pre_status_assume(out, op, lifecycle);

            for (pname, ptype) in &op.takes_params {
                out.push_str(&format!(
                    "    let {}: {} = kani::any();\n",
                    pname,
                    map_type(ptype, parsed)?
                ));
            }
            // Deliberate double-emit — see guard-enforcement comment.
            util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;
            util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;

            emit_kani_account_env_binding(out, op, "accounts", "    ");
            let abort_expr =
                util::rewrite_account_pubkey_refs(&abort.rust_expr, &op.accounts, "accounts");
            let abort_expr = util::rewrite_kani_pubkey_comparisons(&abort_expr, op, parsed);
            out.push_str(&format!("    kani::assume({});\n", abort_expr));

            let args = transition_call_args(
                op,
                util::handler_needs_account_env(op).then_some("accounts"),
            );
            out.push_str(&format!("    assert!(!{}(&mut s{}),\n", op.name, args));
            out.push_str(&format!(
                "        \"{} must abort with {}\");\n",
                op.name, abort.error_name
            ));
            out.push_str("}\n\n");
        }
    }

    Ok(())
}

// ----------------------------------------------------------------------
// Section emitters — property-preservation harnesses
// ----------------------------------------------------------------------

/// Emit `#[kani::proof] fn verify_<handler>_preserves_<property>()` per
/// `(property, handler)` pair named in the property's `preserved_by` list.
///
/// Shape: pre-state zeroed for init handlers, symbolic otherwise; non-init
/// adds pre-status assume, optional per-slot binder, pre-property assumes
/// (unary only), and bound assumes; symbolic params + abstract binders;
/// `emit_add_strict_bounds` for add-effect overflow gating; then
/// `if <handler>(&mut post, args) { assert!(<prop>...); }` dispatched on
/// prop class (Binary → `prop(&pre, &post)`, per-slot Unary →
/// `prop_at(&post, binder)`, plain Unary → `prop(&post)`).
fn emit_property_preservation_harnesses(out: &mut String, parsed: &ParsedSpec) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    if parsed.properties.is_empty() {
        return Ok(());
    }

    // Resolve view — same logic as `emit_account_section_structural`.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Property preservation — invariants hold through all transitions\n");
    out.push_str(
        "// ============================================================================\n\n",
    );

    let handlers: Vec<&crate::check::ParsedHandler> = parsed.handlers.iter().collect();
    let properties: Vec<&crate::check::ParsedProperty> = parsed.properties.iter().collect();

    for prop in &properties {
        if prop.expression.is_none() {
            continue;
        }

        for op_name in &prop.preserved_by {
            // Skip handlers not in this section's scoped view.
            let Some(op) = handlers.iter().copied().find(|o| &o.name == op_name) else {
                continue;
            };

            out.push_str("#[kani::proof]\n");
            out.push_str("#[kani::unwind(2)]\n");
            out.push_str("#[kani::solver(cadical)]\n");
            out.push_str(&format!(
                "fn verify_{}_preserves_{}() {{\n",
                op_name, prop.name
            ));

            let is_init = op.pre_status.as_deref() == Some("Uninitialized");

            // Per-slot binder: skip the local binding when the handler
            // param shadows it (same binder pre & post unifies the value).
            let handler_takes_binder = match &prop.per_slot {
                Some(slot) => op
                    .takes_params
                    .iter()
                    .any(|(n, t)| n == &slot.binder_name && t == &slot.binder_type),
                _ => false,
            };
            let needs_local_binder = prop.per_slot.is_some() && !handler_takes_binder;

            if is_init {
                // Init handler — pre-state is zeroed.
                out.push_str("    let pre = ");
                out.push_str("State {\n");
                for (fname, ftype) in &mutable {
                    if let Some(default) = parsed.default_value_for_type(ftype) {
                        out.push_str(&format!("        {}: {},\n", fname, default));
                    }
                }
                if let Some(initial) = lifecycle.first() {
                    if lifecycle.len() >= 2 {
                        out.push_str(&format!("        status: Status::{},\n", initial));
                    }
                }
                out.push_str("    };\n");
                out.push_str("    let mut post = pre;\n");
            } else {
                // Non-init — pre is symbolic.
                out.push_str("    let pre = State {\n");
                for (fname, _) in &mutable {
                    out.push_str(&format!("        {}: kani::any(),\n", fname));
                }
                if lifecycle.len() >= 2 {
                    out.push_str("        status: kani::any(),\n");
                }
                out.push_str("    };\n");
                if lifecycle.len() >= 2 {
                    if let Some(ref pre_status) = op.pre_status {
                        out.push_str(&format!(
                            "    kani::assume(pre.status == Status::{});\n",
                            pre_status
                        ));
                    }
                }

                if needs_local_binder {
                    if let Some(slot) = &prop.per_slot {
                        let rust_ty = map_type(&slot.binder_type, parsed)?;
                        out.push_str(&format!(
                            "    let {}: {} = kani::any();\n",
                            slot.binder_name, rust_ty
                        ));
                    }
                }

                // Assume unary pre-properties hold; skip Binary (their
                // `(pre, post)` shape asserts trivially against `(pre, pre)`).
                for pre_prop in &properties {
                    if pre_prop.expression.is_none() {
                        continue;
                    }
                    if pre_prop.class == crate::check::PropertyClass::Binary {
                        continue;
                    }
                    match &pre_prop.per_slot {
                        Some(slot) if pre_prop.name == prop.name => {
                            out.push_str(&format!(
                                "    kani::assume({}_at(&pre, {}));\n",
                                pre_prop.name, slot.binder_name
                            ));
                        }
                        _ => {
                            out.push_str(&format!("    kani::assume({}(&pre));\n", pre_prop.name));
                        }
                    }
                }

                // Heuristic MAX*/MEMBER* constant bound on member_count.
                if !parsed.constants.is_empty() {
                    for (cname, _cval) in &parsed.constants {
                        let upper = cname.to_uppercase();
                        if upper.contains("MAX") || upper.contains("MEMBER") {
                            if mutable.iter().any(|(f, _)| f == "member_count") {
                                out.push_str(&format!(
                                    "    kani::assume(pre.member_count <= {});\n",
                                    upper
                                ));
                            }
                            break;
                        }
                    }
                }

                out.push_str("    let mut post = pre;\n");
            }

            for (pname, ptype) in &op.takes_params {
                out.push_str(&format!(
                    "    let {}: {} = kani::any();\n",
                    pname,
                    map_type(ptype, parsed)?
                ));
            }
            // Single abstract-binder emit here (not the double-emit of the
            // guard/abort sections).
            util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;

            let owned_props: Vec<crate::check::ParsedProperty> =
                properties.iter().map(|p| (*p).clone()).collect();
            util::emit_add_strict_bounds(
                out,
                op,
                &owned_props,
                "    kani::assume(pre.{field} < pre.{bound}); // strict bound: {field} increments\n",
            );

            emit_kani_account_env_binding(out, op, "accounts", "    ");
            let args = transition_call_args(
                op,
                util::handler_needs_account_env(op).then_some("accounts"),
            );
            out.push_str(&format!("    if {}(&mut post{}) {{\n", op_name, args));
            let is_binary_prop = prop.class == crate::check::PropertyClass::Binary;
            if is_binary_prop {
                out.push_str(&format!("        assert!({}(&pre, &post),\n", prop.name));
                out.push_str(&format!(
                    "            \"{} must hold after {} (binary: pre/post)\");\n",
                    prop.name, op_name
                ));
            } else {
                match &prop.per_slot {
                    Some(slot) => {
                        out.push_str(&format!(
                            "        assert!({}_at(&post, {}),\n",
                            prop.name, slot.binder_name
                        ));
                        out.push_str(&format!(
                            "            \"{} must hold after {} (forall {} : {})\");\n",
                            prop.name, op_name, slot.binder_name, slot.binder_type
                        ));
                    }
                    None => {
                        out.push_str(&format!("        assert!({}(&post),\n", prop.name));
                        out.push_str(&format!(
                            "            \"{} must hold after {}\");\n",
                            prop.name, op_name
                        ));
                    }
                }
            }
            out.push_str("    }\n");
            out.push_str("}\n\n");
        }
    }

    Ok(())
}

// ----------------------------------------------------------------------
// Section emitters — ensures-preservation harnesses
// ----------------------------------------------------------------------

/// Emit `#[kani::proof] fn verify_<handler>_ensures_<idx>()` per
/// `(handler, ensures clause)` pair.
///
/// Shape: symbolic state + params + binders; `kani::assume(<full_guard>)`
/// so only pre-states the transition wouldn't reject are explored
/// (otherwise the ensures passes vacuously); `pre` snapshot AFTER the
/// assumes; then inside `if <handler>(...)`, `let post = &s;` binds the
/// ensures' `post.x` paths and the clause is asserted.
///
/// CPI ensures-as-fact: each `call Iface.foo(args)` whose callee declares
/// ensures gets the callee contract substituted with caller call-site
/// expressions and `kani::assume`d as a fact in the caller's harness.
/// Tier-0 callees (no ensures) emit nothing — the `cpi_no_callee_ensures`
/// lint surfaces this.
///
/// Position load-bearing: must sit between property-preservation and
/// invariant-preservation for snapshot byte-equivalence.
fn emit_ensures_preservation_harnesses(out: &mut String, parsed: &ParsedSpec) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    let handlers: Vec<&crate::check::ParsedHandler> = parsed.handlers.iter().collect();

    let handlers_with_ensures: Vec<&crate::check::ParsedHandler> = handlers
        .iter()
        .copied()
        .filter(|h| !h.ensures.is_empty())
        .collect();

    if handlers_with_ensures.is_empty() {
        return Ok(());
    }

    // Resolve view.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Ensures preservation — `ensures <expr>` clauses verified against\n");
    out.push_str("// (pre, post) of the spec-translated transition. Counterexamples here\n");
    out.push_str("// indicate the spec's effect block doesn't satisfy its own ensures —\n");
    out.push_str("// usually because the math lives in the user's Rust impl, behind a\n");
    out.push_str("// `modifies`-driven todo!() fill site. See SKILL.md §ref_impl.\n");
    out.push_str(
        "// ============================================================================\n\n",
    );

    for op in handlers_with_ensures {
        for (idx, ensures) in op.ensures.iter().enumerate() {
            out.push_str("#[kani::proof]\n");
            out.push_str("#[kani::unwind(2)]\n");
            out.push_str("#[kani::solver(cadical)]\n");
            out.push_str(&format!("fn verify_{}_ensures_{}() {{\n", op.name, idx));

            util::emit_state_init_symbolic(out, &mutable, lifecycle);
            util::emit_pre_status_assume(out, op, lifecycle);

            for (pname, ptype) in &op.takes_params {
                out.push_str(&format!(
                    "    let {}: {} = kani::any();\n",
                    pname,
                    map_type(ptype, parsed)?
                ));
            }
            util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;

            // Assume requires hold pre-state (avoid vacuous pass).
            emit_kani_account_env_binding(out, op, "accounts", "    ");
            if let Some(full_guard) = util::collect_full_guard_with_account_env(
                op,
                false,
                util::handler_needs_account_env(op).then_some("accounts"),
            ) {
                let full_guard = util::rewrite_kani_pubkey_comparisons(&full_guard, op, parsed);
                out.push_str(&format!("    kani::assume({});\n", full_guard));
            }

            // Snapshot AFTER assumes — pre reflects the constrained
            // pre-state Kani explores.
            out.push_str("    let pre = s.clone();\n");

            let args = transition_call_args(
                op,
                util::handler_needs_account_env(op).then_some("accounts"),
            );
            out.push_str(&format!("    if {}(&mut s{}) {{\n", op.name, args));
            out.push_str("        let post = &s;\n");

            // CPI ensures-as-fact propagation.
            for call in &op.calls {
                let Some(iface) = parsed
                    .interfaces
                    .iter()
                    .find(|i| i.name == call.target_interface)
                else {
                    continue;
                };
                let Some(callee_handler) = iface
                    .handlers
                    .iter()
                    .find(|h| h.name == call.target_handler)
                else {
                    continue;
                };
                if callee_handler.ensures.is_empty() {
                    continue;
                }
                out.push_str(&format!(
                    "        // CPI ensures-as-fact ({}.{}):\n",
                    call.target_interface, call.target_handler,
                ));
                for callee_ens in &callee_handler.ensures {
                    let abstract_fields = crate::cpi_substitute::scan_rust_abstract_fields(
                        &callee_ens.rust_expr_binary,
                    );
                    let missing = crate::cpi_substitute::missing_state_binders(
                        &abstract_fields,
                        &call.state_binders,
                    );
                    if !missing.is_empty() {
                        out.push_str(&format!(
                            "        // `{}.{}` ensures skipped: missing `state_binders` for {}.\n",
                            call.target_interface,
                            call.target_handler,
                            missing.join(", "),
                        ));
                        continue;
                    }
                    let substituted = crate::cpi_substitute::substitute_callee_ensures_rust_binary(
                        &callee_ens.rust_expr_binary,
                        call,
                        &callee_handler.params,
                        callee_handler.result_binder.as_deref(),
                    );
                    let substituted =
                        util::rewrite_kani_pubkey_comparisons(&substituted, op, parsed);
                    out.push_str(&format!("        kani::assume({});\n", substituted));
                }
            }

            let ensures_expr =
                util::rewrite_kani_pubkey_comparisons(&ensures.rust_expr_binary, op, parsed);
            out.push_str(&format!("        assert!({},\n", ensures_expr));
            out.push_str(&format!(
                "            \"ensures clause {} on {} violated by spec-translated transition\");\n",
                idx, op.name
            ));
            out.push_str("    }\n");
            out.push_str("}\n\n");

            // Intentional no-op — see `pre_unused_workaround_needed`.
            let _ = pre_unused_workaround_needed(ensures);
        }
    }

    Ok(())
}

/// No-op stub for the `pre`-binding lint workaround: deliberately emits
/// nothing extra (underscoring `pre` conditionally proved too brittle);
/// the call marks intent to keep the snapshot-pinned byte-exact shape.
fn pre_unused_workaround_needed(_ensures: &crate::check::ParsedEnsures) -> bool {
    false
}

// ----------------------------------------------------------------------
// Section emitters — invariant-preservation harnesses
// ----------------------------------------------------------------------

/// Emit `#[kani::proof] fn verify_<handler>_(preserves|establishes)_<invariant>()`
/// per handler × invariant-clause pair (`op.invariants` ∪ `op.establishes`).
/// Skips invariants with missing/unsupported `rust_expr`. Pre-state zeroed
/// for init handlers, else symbolic; preserves assumes `<inv>(&s)` pre to
/// scope BMC to states where it already holds; establishes deliberately
/// skips that pre-assume (the handler must *make* it true regardless).
/// Then `if <handler>(&mut s, ...) { assert!(<inv>(&s)); }`.
fn emit_invariant_preservation_harnesses(out: &mut String, parsed: &ParsedSpec) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    let handlers: Vec<&crate::check::ParsedHandler> = parsed.handlers.iter().collect();

    // Invariants referenced by at least one handler in this section.
    let linked_invs: Vec<&crate::check::ParsedInvariant> = parsed
        .invariants
        .iter()
        .filter(|i| {
            handlers
                .iter()
                .any(|h| h.invariants.contains(&i.name) || h.establishes.contains(&i.name))
        })
        .collect();

    if linked_invs.is_empty() {
        return Ok(());
    }

    // Resolve view — same logic as `emit_account_section_structural`.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Invariant preservation — `invariant Name` on a handler asserts the named\n");
    out.push_str("// top-level invariant holds before AND after the handler runs. Each pair\n");
    out.push_str("// becomes its own BMC proof.\n");
    out.push_str(
        "// ============================================================================\n\n",
    );

    for op in &handlers {
        let pairs: Vec<(&String, bool)> = op
            .invariants
            .iter()
            .map(|n| (n, false))
            .chain(op.establishes.iter().map(|n| (n, true)))
            .collect();

        for (inv_name, is_establish) in pairs {
            let Some(inv) = linked_invs.iter().find(|i| &i.name == inv_name) else {
                continue;
            };
            // Skip missing/unsupported bodies (e.g. QEDGEN_UNSUPPORTED_QUANTIFIER).
            if inv
                .rust_expr
                .as_deref()
                .map(crate::check::rust_expr_is_unsupported)
                .unwrap_or(true)
            {
                continue;
            }

            let is_init = op.pre_status.as_deref() == Some("Uninitialized");

            out.push_str("#[kani::proof]\n");
            out.push_str("#[kani::unwind(2)]\n");
            out.push_str("#[kani::solver(cadical)]\n");
            let verb = if is_establish {
                "establishes"
            } else {
                "preserves"
            };
            out.push_str(&format!(
                "fn verify_{}_{}_{}() {{\n",
                op.name, verb, inv.name
            ));

            if is_init {
                util::emit_state_init_zeroed(out, &mutable, lifecycle, parsed);
            } else {
                util::emit_state_init_symbolic(out, &mutable, lifecycle);
                util::emit_pre_status_assume(out, op, lifecycle);
                if !is_establish {
                    out.push_str(&format!("    kani::assume({}(&s));\n", inv.name));
                }
            }

            for (pname, ptype) in &op.takes_params {
                out.push_str(&format!(
                    "    let {}: {} = kani::any();\n",
                    pname,
                    map_type(ptype, parsed)?
                ));
            }
            util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;

            let args: String = op
                .takes_params
                .iter()
                .chain(op.abstract_binders.iter())
                .map(|(n, _)| format!(", {}", n))
                .collect();
            out.push_str(&format!("    if {}(&mut s{}) {{\n", op.name, args));
            out.push_str(&format!("        assert!({}(&s),\n", inv.name));
            out.push_str(&format!(
                "            \"invariant {} must hold after {}\");\n",
                inv.name, op.name
            ));
            out.push_str("    }\n");
            out.push_str("}\n\n");
        }
    }

    Ok(())
}

// ----------------------------------------------------------------------
// Section emitters — effect-conformance harnesses
// ----------------------------------------------------------------------

/// Per-(handler, field) effect-conformance harnesses — one proof per pair
/// so a single stuck mul/div field can't block sibling-field verification.
/// Solver per harness via `pick_kani_solver_for_effect`: cadical (scalar /
/// linear, default), minisat (narrow-type mul/div), z3 (wide-type mul/div).
///
/// Body: skip fields whose base isn't in this section's State (multi-account
/// safety); zeroed/symbolic pre-state; `pre_<F>` snapshots for every mutable
/// field (skipping the target of a `set`); then under `if <handler>(...)`:
/// set → `s.F == <resolved>`, add/sub → `s.F == pre_F.wrapping_{add,sub}(<resolved>)`;
/// sibling fields assert `s.G == pre_G` unless another effect in the same
/// handler mutates them.
fn emit_effect_conformance_harnesses(
    out: &mut String,
    mir: &Mir,
    parsed: &ParsedSpec,
) -> Result<()> {
    use crate::codegen_shared::sanitize_ident;
    use crate::rust_codegen_util as util;

    let handlers: Vec<&crate::check::ParsedHandler> = parsed.handlers.iter().collect();

    let effect_ops: Vec<&crate::check::ParsedHandler> = handlers
        .iter()
        .copied()
        .filter(|op| op.has_effect())
        .collect();

    if effect_ops.is_empty() {
        return Ok(());
    }

    // Resolve view.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);
    let properties: Vec<&crate::check::ParsedProperty> = parsed.properties.iter().collect();

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Effect conformance — verify transition effects match spec\n");
    out.push_str("//\n");
    out.push_str("// Each proof applies a transition to symbolic state and checks that every\n");
    out.push_str("// field changed/unchanged matches the spec's effect: declarations.\n");
    out.push_str(
        "// ============================================================================\n\n",
    );

    let field_type_lookup: std::collections::HashMap<&str, &str> = mutable
        .iter()
        .map(|(n, t)| (n.as_str(), t.as_str()))
        .collect();

    for op in &effect_ops {
        // Iterate the handler's lowered MIR body projected onto triples
        // (not `op.effects`); the sibling-frame check reads the same list.
        let body = mir
            .handler_block(&op.name)
            .ok_or_else(|| anyhow::anyhow!("MIR has no handler `{}`", op.name))?;
        let triples = util::block_effect_triples(body);
        for (field, op_kind, value) in triples.iter().cloned() {
            let harness_name = format!("verify_{}_effect_{}", op.name, sanitize_ident(&field));
            emit_one_conformance_harness(
                out,
                parsed,
                op,
                &mutable,
                lifecycle,
                &properties,
                &field_type_lookup,
                &harness_name,
                &[],
                (&field, op_kind, value),
                &triples,
            )?;
        }

        // Conditional effects: one harness per (arm, effect) under a
        // `kani::assume(<scrutinee> == <pattern>)` pin, so post-state
        // assertions hold under match semantics (exactly one arm fires).
        // The sibling-frame check is scoped to the arm's own effects —
        // with the arm pinned, no other arm can mutate. The wildcard arm
        // pins via negated assumes over every literal pattern.
        let branch = body.stmts.iter().find_map(|st| match st {
            crate::mir::Stmt::Branch {
                scrutinee,
                arms,
                default,
            } => Some((scrutinee, arms, default)),
            _ => None,
        });
        if let Some((scrutinee, arms, default)) = branch {
            let scrut = match scrutinee {
                crate::mir::BranchScrutinee::Match(e) => e.rust.as_str(),
                crate::mir::BranchScrutinee::Predicate(p) => p.0.rust.as_str(),
            };
            let patterns: Vec<&str> = arms
                .iter()
                .filter_map(|a| a.pattern.as_ref().map(|p| p.rust.as_str()))
                .collect();
            for (idx, arm) in arms.iter().enumerate() {
                let Some(pattern) = arm.pattern.as_ref().map(|p| p.rust.as_str()) else {
                    continue;
                };
                let assume = vec![format!("    kani::assume({} == {});\n", scrut, pattern)];
                let arm_triples = util::block_effect_triples(&arm.block);
                for (field, op_kind, value) in arm_triples.iter().cloned() {
                    let harness_name = format!(
                        "verify_{}_arm{}_effect_{}",
                        op.name,
                        idx,
                        sanitize_ident(&field)
                    );
                    emit_one_conformance_harness(
                        out,
                        parsed,
                        op,
                        &mutable,
                        lifecycle,
                        &properties,
                        &field_type_lookup,
                        &harness_name,
                        &assume,
                        (&field, op_kind, value),
                        &arm_triples,
                    )?;
                }
            }
            if let Some(default_block) = default {
                let assumes: Vec<String> = patterns
                    .iter()
                    .map(|p| format!("    kani::assume({} != {});\n", scrut, p))
                    .collect();
                let default_triples = util::block_effect_triples(default_block);
                for (field, op_kind, value) in default_triples.iter().cloned() {
                    let harness_name = format!(
                        "verify_{}_default_effect_{}",
                        op.name,
                        sanitize_ident(&field)
                    );
                    emit_one_conformance_harness(
                        out,
                        parsed,
                        op,
                        &mutable,
                        lifecycle,
                        &properties,
                        &field_type_lookup,
                        &harness_name,
                        &assumes,
                        (&field, op_kind, value),
                        &default_triples,
                    )?;
                }
            }
        }
    }

    Ok(())
}

/// One effect-conformance harness: symbolic (or zeroed-init) state,
/// symbolic params, optional scrutinee-pin assumes (per-arm sites),
/// transition call, post-state assertion for the target effect, and the
/// frame check over `sibling_triples` (the effect set that can legally
/// fire alongside the target — the whole flat body, or one Branch arm).
#[allow(clippy::too_many_arguments)]
fn emit_one_conformance_harness(
    out: &mut String,
    parsed: &ParsedSpec,
    op: &crate::check::ParsedHandler,
    mutable: &[&(String, String)],
    lifecycle: &[String],
    properties: &[&crate::check::ParsedProperty],
    field_type_lookup: &std::collections::HashMap<&str, &str>,
    harness_name: &str,
    assume_lines: &[String],
    (field, op_kind, value): (&str, &str, &str),
    sibling_triples: &[(String, &'static str, &str)],
) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    let is_init = op.pre_status.as_deref() == Some("Uninitialized");

    let base = util::effect_target_base(field);
    if !field_type_lookup.contains_key(base) {
        return Ok(());
    }

    let field_type = field_type_lookup.get(field).copied().unwrap_or("");
    let solver = util::pick_kani_solver_for_effect(field_type, value, op);

    out.push_str("#[kani::proof]\n");
    out.push_str("#[kani::unwind(2)]\n");
    out.push_str(&format!("#[kani::solver({})]\n", solver));
    out.push_str(&format!("fn {}() {{\n", harness_name));

    if is_init {
        util::emit_state_init_zeroed(out, mutable, lifecycle, parsed);
    } else {
        util::emit_state_init_symbolic(out, mutable, lifecycle);
        util::emit_pre_status_assume(out, op, lifecycle);
    }

    for (pname, ptype) in &op.takes_params {
        out.push_str(&format!(
            "    let {}: {} = kani::any();\n",
            pname,
            map_type(ptype, parsed)?
        ));
    }
    util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;

    // Pin the scrutinee to this arm (or away from every literal pattern,
    // for the wildcard arm) before any state is read.
    for line in assume_lines {
        out.push_str(line);
    }

    // Bounds assumptions for arithmetic safety (non-init only).
    if !is_init {
        if !parsed.constants.is_empty() {
            for (cname, _) in &parsed.constants {
                let upper = cname.to_uppercase();
                if upper.contains("MAX") || upper.contains("MEMBER") {
                    if mutable.iter().any(|(f, _)| f == "member_count") {
                        out.push_str(&format!("    kani::assume(s.member_count <= {});\n", upper));
                    }
                    break;
                }
            }
        }
        let owned_props: Vec<crate::check::ParsedProperty> =
            properties.iter().map(|p| (*p).clone()).collect();
        util::emit_add_strict_bounds(
            out,
            op,
            &owned_props,
            "    kani::assume(s.{field} < s.{bound}); // strict bound: {field} increments\n",
        );
    }

    // Pre-state snapshot — every mutable field except the
    // set-target.
    let needs_pre_for: Vec<&&(String, String)> = mutable
        .iter()
        .filter(|(fname, _)| !(fname.as_str() == field && op_kind == "set"))
        .collect();
    for (fname, _) in &needs_pre_for {
        out.push_str(&format!("    let pre_{} = s.{};\n", fname, fname));
    }

    emit_kani_account_env_binding(out, op, "accounts", "    ");
    let args = transition_call_args(
        op,
        util::handler_needs_account_env(op).then_some("accounts"),
    );
    out.push_str(&format!("    if {}(&mut s{}) {{\n", op.name, args));

    let resolved = util::resolve_value_with_account_env(
        value,
        op,
        parsed,
        Some("pre_"),
        util::handler_needs_account_env(op).then_some("accounts"),
    );
    match op_kind {
        "set" => {
            let assertion = util::rewrite_kani_pubkey_comparisons(
                &format!("s.{field} == {resolved}"),
                op,
                parsed,
            );
            out.push_str(&format!(
                "        assert!({}, \"{} must equal {}\");\n",
                assertion, field, resolved
            ));
        }
        "add" => {
            out.push_str(&format!(
                "        assert!(s.{} == pre_{}.wrapping_add({}), \"{} must increment by {}\");\n",
                field, field, resolved, field, resolved
            ));
        }
        "sub" => {
            out.push_str(&format!(
                "        assert!(s.{} == pre_{}.wrapping_sub({}), \"{} must decrement by {}\");\n",
                field, field, resolved, field, resolved
            ));
        }
        _ => {}
    }

    // Assert sibling fields unchanged (unless mutated by another
    // effect in the same frame — the flat body, or this arm).
    for (fname, _) in mutable {
        if fname.as_str() != field {
            let sibling_mutated = sibling_triples
                .iter()
                .any(|(f, _, _)| f.as_str() == fname.as_str());
            if !sibling_mutated {
                let assertion = util::rewrite_kani_pubkey_comparisons(
                    &format!("s.{fname} == pre_{fname}"),
                    op,
                    parsed,
                );
                out.push_str(&format!(
                    "        assert!({}, \"{} must not change\");\n",
                    assertion, fname
                ));
            }
        }
    }

    out.push_str("    }\n");
    out.push_str("}\n\n");
    Ok(())
}

// ----------------------------------------------------------------------
// Section emitters — overflow-detection harnesses
// ----------------------------------------------------------------------

/// Emit `#[kani::proof] fn verify_<handler>_no_overflow()` per handler
/// with an `add` effect. No explicit assert — Kani's built-in overflow
/// detection fires on `+=` inside the transition body; the proof exists
/// to drive BMC across the parameter space.
fn emit_overflow_detection_harnesses(
    out: &mut String,
    mir: &Mir,
    parsed: &ParsedSpec,
) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    let handlers: Vec<&crate::check::ParsedHandler> = parsed.handlers.iter().collect();

    // Checked-add filter reads the lowered MIR body (`Stmt::CheckedAdd`
    // projects to kind "add"), deep-walked: a checked add inside a
    // `Stmt::Branch` arm can still overflow, and the harness just invokes
    // the transition (Kani explores every match arm).
    let overflow_ops: Vec<&crate::check::ParsedHandler> = handlers
        .iter()
        .copied()
        .filter(|op| {
            mir.handler_block(&op.name).is_some_and(|body| {
                util::block_effect_triples_deep(body)
                    .iter()
                    .any(|(_, kind, _)| *kind == "add")
            })
        })
        .collect();

    if overflow_ops.is_empty() {
        return Ok(());
    }

    // Resolve view.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else if parsed.account_types.is_empty() {
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        } else {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);

    out.push_str(
        "// ============================================================================\n",
    );
    out.push_str("// Overflow detection — Kani catches arithmetic overflow on add effects\n");
    out.push_str(
        "// ============================================================================\n\n",
    );

    for op in &overflow_ops {
        out.push_str("#[kani::proof]\n");
        out.push_str("#[kani::unwind(2)]\n");
        out.push_str("#[kani::solver(cadical)]\n");
        out.push_str(&format!("fn verify_{}_no_overflow() {{\n", op.name));

        util::emit_state_init_symbolic(out, &mutable, lifecycle);
        util::emit_pre_status_assume(out, op, lifecycle);

        for (pname, ptype) in &op.takes_params {
            out.push_str(&format!(
                "    let {}: {} = kani::any();\n",
                pname,
                map_type(ptype, parsed)?
            ));
        }
        util::emit_abstract_binders(out, op, "    ", "kani::any()", |t| map_type(t, parsed))?;

        emit_kani_account_env_binding(out, op, "accounts", "    ");
        let args = transition_call_args(
            op,
            util::handler_needs_account_env(op).then_some("accounts"),
        );
        out.push_str(&format!(
            "    {}(&mut s{});  // Kani detects overflow on += internally\n",
            op.name, args
        ));
        out.push_str("}\n\n");
    }

    Ok(())
}

// ----------------------------------------------------------------------
// Section emitters — file-level features (single-mode only)
// ----------------------------------------------------------------------

/// Covers / liveness / environment harnesses at file scope. These reference
/// handlers by name and the per-spec `State` directly, so they only fire in
/// single-account mode; multi-account specs skip them.
///
///   1. Covers (reachability) — per `(cover, trace)` pair, nested `if`
///      chain over the trace handlers capped with `kani::cover!(<last_op>(...))`.
///   2. Liveness (bounded reachability) — assume the from-state, loop
///      `0..bound` dispatching via_ops on a non-deterministic `op: u8`,
///      then `kani::cover!(s.status == Status::<to_state>)`. Skipped (with
///      a structured comment) when the spec has no lifecycle.
///   3. Environment — per `(env, property)` cross: assume the property pre,
///      mutate `env.mutates` fields to `kani::any()`, assume the
///      constraints, then `assert!(<prop>(&s))`.
fn emit_file_level_features(out: &mut String, parsed: &ParsedSpec) -> Result<()> {
    use crate::codegen_shared::map_type;
    use crate::rust_codegen_util as util;

    // Resolve view — same logic as `emit_account_section_structural`.
    let (state_fields, lifecycle): (&[(String, String)], &[String]) =
        if parsed.account_types.len() == 1 {
            (
                &parsed.account_types[0].fields,
                parsed.account_types[0].lifecycle.as_slice(),
            )
        } else {
            // Zero account types — flat state form.
            (
                util::resolve_state_fields(parsed),
                parsed.lifecycle_states.as_slice(),
            )
        };
    let mutable = util::mutable_fields(state_fields);
    let has_lifecycle = lifecycle.len() >= 2;

    // ── Cover properties ──────────────────────────────────────────
    if !parsed.covers.is_empty() {
        out.push_str(
            "// ============================================================================\n",
        );
        out.push_str("// Cover properties — reachability via kani::cover!\n");
        out.push_str(
            "// ============================================================================\n\n",
        );

        for cover in &parsed.covers {
            for (i, trace) in cover.traces.iter().enumerate() {
                let suffix = if cover.traces.len() > 1 {
                    format!("_{}", i)
                } else {
                    String::new()
                };
                out.push_str("#[kani::proof]\n");
                let unwind = trace.len() + 1;
                out.push_str(&format!("#[kani::unwind({})]\n", unwind));
                out.push_str("#[kani::solver(cadical)]\n");
                out.push_str(&format!("fn cover_{}{}() {{\n", cover.name, suffix));

                util::emit_state_init_symbolic(out, &mutable, lifecycle);

                let mut indent = "    ".to_string();
                for (j, op_name) in trace.iter().enumerate() {
                    let op = parsed.handlers.iter().find(|o| o.name == *op_name);
                    if let Some(op) = op {
                        for (pname, ptype) in &op.takes_params {
                            out.push_str(&format!(
                                "{}let {}_{}: {} = kani::any();\n",
                                indent,
                                pname,
                                j,
                                map_type(ptype, parsed)?
                            ));
                        }
                    }
                    if let Some(o) = op {
                        emit_kani_account_env_binding(out, o, &format!("accounts_{}", j), &indent);
                    }
                    let args: String = op
                        .map(|o| {
                            let mut args = String::new();
                            if util::handler_needs_account_env(o) {
                                args.push_str(&format!(", &accounts_{}", j));
                            }
                            for (n, _) in &o.takes_params {
                                args.push_str(&format!(", {}_{}", n, j));
                            }
                            args
                        })
                        .unwrap_or_default();

                    if j < trace.len() - 1 {
                        out.push_str(&format!("{}if {}(&mut s{}) {{\n", indent, op_name, args));
                        indent.push_str("    ");
                    } else {
                        out.push_str(&format!(
                            "{}kani::cover!({}(&mut s{}), \"{} trace is reachable\");\n",
                            indent, op_name, args, cover.name
                        ));
                    }
                }
                // Close braces (one less than trace length).
                for _ in 0..trace.len().saturating_sub(1) {
                    indent = indent[..indent.len() - 4].to_string();
                    out.push_str(&format!("{}}}\n", indent));
                }
                out.push_str("}\n\n");
            }
        }
    }

    // ── Liveness properties ──────────────────────────────────────
    if !parsed.liveness_props.is_empty() {
        out.push_str(
            "// ============================================================================\n",
        );
        out.push_str("// Liveness properties — bounded reachability via non-deterministic ops\n");
        out.push_str(
            "// ============================================================================\n\n",
        );

        for liveness in &parsed.liveness_props {
            let bound = liveness.within_steps.unwrap_or(10) as usize;

            // No lifecycle → no target predicate; skip with a structured comment.
            if !has_lifecycle {
                out.push_str(&format!(
                    "// liveness {}: skipped — spec has no lifecycle, no target predicate to cover\n\n",
                    liveness.name
                ));
                continue;
            }

            out.push_str("#[kani::proof]\n");
            out.push_str(&format!("#[kani::unwind({})]\n", bound + 1));
            out.push_str("#[kani::solver(cadical)]\n");
            out.push_str(&format!("fn verify_liveness_{}() {{\n", liveness.name));

            util::emit_state_init_symbolic(out, &mutable, lifecycle);

            // Assume the from-state so via-ops can fire.
            out.push_str(&format!(
                "    kani::assume(s.status == Status::{});\n",
                liveness.from_state
            ));

            let via_ops = &liveness.via_ops;
            out.push_str(&format!("    for _ in 0..{} {{\n", bound));
            out.push_str("        let op: u8 = kani::any();\n");
            out.push_str("        match op {\n");
            for (i, op_name) in via_ops.iter().enumerate() {
                let op = parsed.handlers.iter().find(|o| o.name == *op_name);
                let param_decls: String = match op {
                    Some(o) => o
                        .takes_params
                        .iter()
                        .map(|(n, t)| {
                            map_type(t, parsed)
                                .map(|rt| format!("            let {}: {} = kani::any();\n", n, rt))
                        })
                        .collect::<anyhow::Result<String>>()?,
                    None => String::new(),
                };
                let args: String = op
                    .map(|o| {
                        transition_call_args(
                            o,
                            util::handler_needs_account_env(o).then_some("accounts"),
                        )
                    })
                    .unwrap_or_default();

                out.push_str(&format!("            {} => {{\n", i));
                out.push_str(&param_decls);
                if let Some(o) = op {
                    emit_kani_account_env_binding(out, o, "accounts", "            ");
                }
                out.push_str(&format!("                {}(&mut s{});\n", op_name, args));
                out.push_str("            }\n");
            }
            out.push_str("            _ => {}\n");
            out.push_str("        }\n");
            out.push_str("    }\n");

            out.push_str(&format!(
                "    kani::cover!(s.status == Status::{}, \"{} reaches {} within {} steps\");\n",
                liveness.leads_to_state, liveness.name, liveness.leads_to_state, bound
            ));
            out.push_str("}\n\n");
        }
    }

    // ── Environment harnesses ────────────────────────────────────
    if !parsed.environments.is_empty() {
        out.push_str(
            "// ============================================================================\n",
        );
        out.push_str("// Environment — properties hold under external state changes\n");
        out.push_str(
            "// ============================================================================\n\n",
        );

        for env in &parsed.environments {
            for prop in &parsed.properties {
                if prop.expression.is_none() {
                    continue;
                }
                let rust_constraints: &[String] = &env.constraints_rust;

                out.push_str("#[kani::proof]\n");
                out.push_str("#[kani::unwind(2)]\n");
                out.push_str("#[kani::solver(cadical)]\n");
                out.push_str(&format!(
                    "fn verify_{}_under_{}() {{\n",
                    prop.name, env.name
                ));

                util::emit_state_init_symbolic(out, &mutable, lifecycle);
                out.push_str(&format!("    kani::assume({}(&s));\n", prop.name));

                for (field, ftype) in &env.mutates {
                    out.push_str(&format!("    s.{} = kani::any();\n", field));
                    let _ = ftype;
                }
                for constraint in rust_constraints {
                    out.push_str(&format!("    kani::assume({});\n", constraint));
                }

                out.push_str(&format!("    assert!({}(&s),\n", prop.name));
                out.push_str(&format!(
                    "        \"{} must hold after {}\");\n",
                    prop.name, env.name
                ));
                out.push_str("}\n\n");
            }
        }
    }

    Ok(())
}

